pub fn double_ptr(p: *int) {
    *p = *p * 2
}

// double_val returns twice the input, using pointer operations internally.
pub fn double_val(x: int) -> int {
    v := x
    double_ptr(&v)
    return v
}

fn main() -> int {
    result := double_val(49)
    print("Doubled: {result}")
    return 0
}

