module static_rules_0001

import "std/time"

var currentTemp: float = 20.0
var firedCount: int = 0

// TempRules is a static ruleset with a high-temperature rule.
ruleset TempRules {
    rule high when currentTemp > 14.8 {
        action: {
            firedCount = firedCount + 1
        }
        priority: 1
    }
}

// check_high sets the temperature, runs the ruleset briefly, and returns
// the number of times the high rule fired.
pub fn check_high(temp: float) -> int {
    currentTemp = temp
    firedCount = 0
    TempRules.start()
    time.SleepMs(50)
    TempRules.stop()
    time.SleepMs(20)
    TempRules.reset()
    return firedCount
}

fn main() -> int {
    result := check_high(19.8)
    print("Fired: {result}")
    return 0
}

